<?php else:?><section class="setup-main"><h2>صف ارسال و رسیدهای سایت</h2><p>پاسخ موفق افزونه ثبت می‌شود؛ خطای ۴۰۹ یعنی محتوا در سایت تغییر کرده و باید دوباره دریافت و بررسی شود. تلاش مجدد از همان شناسه استفاده می‌کند.</p><?php if(!empty($state['last_error'])):?><p role="alert"><?=wpw_h($state['last_error'])?></p><?php endif;?><form method="post"><?php wpw_csrf();?><button name="action" value="publish" <?=$canWrite?'':'disabled'?>>اجرای یک ارسال آماده</button></form><?php foreach(array_slice(array_reverse($state['jobs']??[]),($page-1)*$limit,$limit) as $job):?><article class="wp-item"><strong><?=wpw_h($job['kind'].' #'.$job['remote_id'])?></strong><p><?=wpw_h(['queued'=>'در صف','done'=>'ارسال موفق','error'=>'ناموفق'][$job['state']]??$job['state'])?></p><?php if(!empty($job['error'])):?><p><?=wpw_h($job['error'])?></p><form method="post"><?php wpw_csrf();?><input type="hidden" name="job_id" value="<?=wpw_h($job['id'])?>"><button name="action" value="retry" <?=$canWrite?'':'disabled'?>>تلاش مجدد</button></form><?php endif;?></article><?php endforeach;?><nav class="wp-nav"><?php if($page>1):?><a href="<?=wpw_h($base.'&view=jobs&page='.($page-1))?>">صفحهٔ قبل</a><?php endif;?><span>صفحه <?=$page?></span><?php if(count($state['jobs']??[])>$page*$limit):?><a href="<?=wpw_h($base.'&view=jobs&page='.($page+1))?>">صفحهٔ بعد</a><?php endif;?></nav><?php if(!empty($state['plan'])):?><details><summary>برنامهٔ بازبینی ثبت‌شده · <?=count($state['plan']['items']??[])?> مورد</summary><p><?=formatPersianDate($state['plan']['at'],'Y/m/d H:i')?></p><p><a href="<?=wpw_h($base.'&download_plan=1')?>">دریافت JSON کامل برنامهٔ بازبینی</a></p><?php foreach(array_slice($state['plan']['items']??[],0,20) as $item):if($item['kind']==='products'&&!canAccessFeature('products','view'))continue;?><article class="wp-item"><strong><?=wpw_h($item['title'])?></strong><p><?=wpw_h(implode('؛ ',$item['issues']))?></p><p><?=wpw_h($item['suggestion'])?></p></article><?php endforeach;?><a href="ai-connect.php?project=<?=rawurlencode($pid)?>&view=reports">گزارش و تحلیل با AI متصل ←</a></details><?php endif;?></section><?php endif;?></main><script>
(()=>{const start=document.getElementById('wp-pull-all'),stop=document.getElementById('wp-pull-stop'),status=document.getElementById('wp-pull-progress');if(!start)return;let running=false,stopped=false;stop.addEventListener('click',()=>{stopped=true;status.textContent='پس از اتمام بستهٔ جاری متوقف می‌شود؛ داده‌های دریافت‌شده حفظ می‌شوند.';});start.addEventListener('click',async()=>{if(running)return;running=true;stopped=false;start.disabled=true;let count=0;const kinds=<?=json_encode(array_values(array_filter(array_keys(WordPressWorkspace::KINDS),static fn($k)=>($k!=='products'||canAccessFeature('products','use'))&&($k!=='sales'||canAccessFeature('sale_analysis','use')))),JSON_UNESCAPED_UNICODE)?>;try{for(const kind of kinds){let next=1;while(next!==null&&!stopped){status.textContent=`در حال دریافت ${kind}؛ ${count} ردیف در این اجرا`;const body=new FormData();body.set('async_pull','1');body.set('kind',kind);body.set('app_csrf',<?=json_encode(RequestSecurity::token())?>);const r=await fetch(location.href,{method:'POST',body});const data=await r.json();if(!r.ok||!data.success)throw new Error(data.error||'دریافت انجام نشد.');count+=data.received;next=data.next_page;}if(stopped)break;}status.textContent=stopped?`متوقف شد؛ ${count} ردیف دریافت شد. برای دیدن آمار صفحه را تازه کنید.`:`دریافت کامل شد؛ ${count} ردیف در این اجرا دریافت شد. صفحه را تازه کنید.`;}catch(e){status.textContent=e.message+' ادامه از آخرین بستهٔ ثبت‌شده ممکن است.';}finally{running=false;start.disabled=false;}});})();
</script></body></html>
